class Student {
    private String name;
    private int age;

    public Student(String name, int age) {
        this.name = name;
        this.age = age;
    }

    public String getInfo() {
        return name + ", " + age;
    }
}

public class Main {
    public static void main(String[] args) {
        Student s = new Student("Tom", 18);
        System.out.println(s.getInfo());
    }
}
